// Types for the generated `astryx-themes.js` module (written by `astryx theme add`).
import type {ComponentProps} from 'react';
import type {Theme} from '@astryxdesign/core/theme';

type AstryxTheme = ComponentProps<typeof Theme>['theme'];

export const themes: Record<string, AstryxTheme>;
export const defaultThemeSlug: string;
